<?php
require __DIR__.'/issuers_core_support.php';
$f=essentialFixture('1.0.2',1);$db=$f->db;$p=$f->prefix;$ip=$p.'issuers_';
$db->query("INSERT INTO {$p}staff VALUES(11,1,0,NULL),(17,0,1,NULL),(19,0,0,NULL)");
$db->query("INSERT INTO {$p}modules VALUES('webhooks','1.0.0',1),('accounting','1.0.0',1),('fleet','1.0.0',0)");
$db->query("INSERT INTO {$p}staff_permissions VALUES(11,'invoices','view_own'),(11,'WEBHOOKS','view'),(11,'custom_existing_resource','existing_cap'),(19,'invoices','edit')");
IssuerCore::reconcile($db,$p);$acl=new IssuerResourceAccess($db,$p);$primary=$acl->primaryId();
essentialCheck($acl->member($primary,7)&&$acl->member($primary,11),'active existing admin and nonadmin retain principal membership');
essentialCheck(!$acl->member($primary,17)&&!$acl->member($primary,19),'inactive employees are not granted effective access');
essentialCheck($acl->can($primary,11,'invoices','view_own'),'exact nonadmin grant preserved');
essentialCheck(!$acl->can($primary,11,'invoices','edit'),'nonadmin gains no additional capability');
essentialCheck($acl->can($primary,11,'WEBHOOKS','view')&&!$acl->can($primary,11,'webhooks','view'),'case-sensitive native resource retained without widening');
essentialCheck($acl->can($primary,11,'custom_existing_resource','existing_cap'),'unregistered but actually stored legacy grant preserved exactly');
essentialCheck($acl->can($primary,7,'settings','edit')&&$acl->can($primary,7,'accounting_rule','create'),'legacy admin receives finite core/active-module catalog including unregistered callsites');
essentialCheck(!$acl->can($primary,7,'fleet_vehicle','view'),'inactive module is not silently granted to ordinary admin');
essentialCheck(!$acl->can($primary,7,'future_module','view'),'new future resource denied to ordinary admin');
essentialCheck(!$acl->isMaster(7),'preservation never infers master');
essentialCheck($acl->administrative($primary,7),'existing principal administrator retains legacy administrative controls without becoming master');
essentialCheck(!$acl->administrative($primary,11),'nonadministrator receives no compatibility administrative grant');
$row=$db->query("SELECT * FROM {$ip}installation_identity WHERE id=1")->row();
essentialCheck((int)$row->legacy_staff_cutoff===19&&strlen($row->legacy_catalog_hash)===64,'one-time cutoff and finite catalog fingerprint stored');
essentialCheck((int)$db->query("SELECT issuer_id FROM {$ip}staff_defaults WHERE staff_id=11")->row()->issuer_id===$primary,'existing user valid default is principal');
$db->query("INSERT INTO {$ip}registry(legal_name,tax_id,active,settings_json,created_by,created_at) VALUES('Synthetic B','12345678000195',1,'{}',7,'2026-10-18 00:00:00')");$other=(int)$db->insert_id();
essentialCheck(!$acl->member($other,7)&&!$acl->member($other,11),'preserved access never crosses to another company');
$db->query("INSERT INTO {$ip}staff(issuer_id,staff_id,can_view) VALUES(?,7,1)",[$other]);
essentialCheck(!$acl->administrative($other,7),'principal administrator is not automatically administrator in B even with B membership');
$db->query("DELETE FROM {$ip}staff_defaults WHERE staff_id=11");$db->query("DELETE FROM {$ip}resource_permissions WHERE staff_id=11");$db->query("DELETE FROM {$ip}staff WHERE staff_id=11");
$db->query("DELETE FROM {$ip}resource_permissions WHERE staff_id=7 AND feature='settings' AND capability='edit'");
$db->query("INSERT INTO {$p}staff VALUES(25,1,1,NULL)");$db->query("UPDATE {$p}modules SET active=1 WHERE module_name='fleet'");$db->query("UPDATE {$p}staff SET active=1 WHERE staffid=19");
IssuerCore::reconcile($db,$p);
essentialCheck(!$acl->member($primary,11),'replay never restores revoked membership');
essentialCheck(!$acl->can($primary,7,'settings','edit'),'replay never restores revoked capability');
essentialCheck(!$acl->member($primary,25),'staff created after cutoff remains default deny even if admin');
essentialCheck(!$acl->member($primary,19),'reactivation after migration does not infer membership');
essentialCheck(!$acl->can($primary,7,'fleet_vehicle','view'),'module activated later has no inherited admin wildcard');
essentialCheck((int)$db->query("SELECT COUNT(*) AS n FROM {$ip}audit WHERE event='legacy_primary_access_preserved'")->row()->n===1,'replay does not duplicate preservation audit');
$db->query("UPDATE {$p}staff SET admin=0 WHERE staffid=7");
essentialCheck(!$acl->administrative($primary,7),'demotion revokes compatibility administration immediately');
$db->query("UPDATE {$p}staff SET admin=1 WHERE staffid=7");
$db->query("DELETE FROM {$ip}resource_permissions WHERE staff_id=7 AND feature='core_legacy_administration'");
essentialCheck(!$acl->administrative($primary,7),'revoking recorded compatibility grant defeats global admin flag');
IssuerCore::reconcile($db,$p);
essentialCheck(!$acl->administrative($primary,7),'repeat migration never resurrects revoked compatibility grant');
// Rollback covers grants, cutoff and audit; no marker may survive a failed preservation unit.
$db->query("UPDATE {$ip}installation_identity SET legacy_access_migrated_at=NULL,legacy_staff_cutoff=NULL,legacy_catalog_hash=NULL WHERE id=1");
$before=$db->query("SELECT * FROM {$ip}resource_permissions ORDER BY staff_id,feature,capability")->result_array();$db->failOn="INSERT INTO {$ip}audit";
essentialThrows(fn()=>IssuerLegacyAccess::apply($db,$p),'issuer_storage_failed','audit failure is sanitized');$db->failOn=null;
essentialCheck($db->query("SELECT legacy_access_migrated_at FROM {$ip}installation_identity WHERE id=1")->row()->legacy_access_migrated_at===null,'failed transaction does not mark preservation complete');
essentialCheck($before===$db->query("SELECT * FROM {$ip}resource_permissions ORDER BY staff_id,feature,capability")->result_array(),'failure rolls back all inserted grants');
essentialCheck(!$acl->member($primary,25),'failure rolls back newly attempted membership');
$db->trans_begin();essentialThrows(fn()=>IssuerLegacyAccess::apply($db,$p),'issuer_outer_transaction_not_allowed','external transaction refused');essentialCheck($db->pdo->inTransaction(),'caller transaction retained');$db->trans_rollback();
$db->query("INSERT INTO {$p}staff_permissions VALUES(11,'bad key','view')");essentialThrows(fn()=>IssuerLegacyAccess::apply($db,$p),'issuer_invalid_permission','malformed persisted key is reported instead of silently discarded');
essentialCheck($db->query("SELECT legacy_access_migrated_at FROM {$ip}installation_identity WHERE id=1")->row()->legacy_access_migrated_at===null,'invalid source cannot advance marker');

// A pre-company resource ACL table is archived verbatim, mapped only into the
// principal company for active members, and never replayed after later revokes.
$legacyFixture=essentialFixture('1.0.2',1);$legacyDb=$legacyFixture->db;$legacyPrefix=$legacyFixture->prefix;$legacyIssuerPrefix=$legacyPrefix.'issuers_';
